using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

// ── Configuration ──────────────────────────────────────────────────
var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var openAiApiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

// ── DI container ───────────────────────────────────────────────────
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddHttpClient();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(openAiApiKey)));

var provider = services.BuildServiceProvider();

var chatClient = provider.GetRequiredService<IChatClient>();
var loggerFactory = provider.GetRequiredService<ILoggerFactory>();

// ── Tools ──────────────────────────────────────────────────────────
var httpClientFactory = provider.GetRequiredService<IHttpClientFactory>();

var webSearch = new WebSearchTool(
    httpClientFactory.CreateClient(),
    configuration["GOOGLE_API_KEY"],
    configuration["GOOGLE_SEARCH_ENGINE_ID"]);

var noteTaking = new NoteTakingTool();

var tools = new List<AITool>();
tools.AddRange(webSearch.AsAITools());
tools.AddRange(noteTaking.AsAITools());

// ── Agent ──────────────────────────────────────────────────────────
const string instructions = """
    You are a research agent. Your job is to thoroughly research a topic
    provided by the user by following these steps:

    1. Use the search_web tool to find information about the topic.
       Perform multiple searches with different queries to get broad coverage.
    2. Use the save_note tool to record key findings from each search.
       Include source URLs for attribution.
    3. After gathering enough information (at least 3-5 notes), use
