using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability to the research agent.
/// Uses the Google Custom Search JSON API when configured,
/// otherwise returns a simulated result for demonstration.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _apiKey;
    private readonly string? _searchEngineId;

    public WebSearchTool(HttpClient httpClient, string? apiKey = null, string? searchEngineId = null)
    {
        _httpClient = httpClient;
        _apiKey = apiKey;
        _searchEngineId = searchEngineId;
    }

    [Description("Searches the web for information on a given query and returns relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrEmpty(_apiKey) && !string.IsNullOrEmpty(_searchEngineId))
        {
            return await SearchWithGoogleApiAsync(query, maxResults);
        }

        return GetSimulatedResults(query, maxResults);
    }

    private async Task<string> SearchWithGoogleApiAsync(string query, int maxResults)
    {
        var encodedQuery = WebUtility.UrlEncode(query);
        var url = $"https://www.googleapis.com/customsearch/v1?key={_apiKey}&cx={_searchEngineId}&q={encodedQuery}&num={maxResults}";

        var response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var results = new List<object>();

        if (json.TryGetProperty("items", out var items))
        {
            foreach (var item in items.EnumerateArray())
            {
                results.Add(new
                {
                    title = item.GetProperty("title").GetString(),
                    snippet = item.GetProperty("snippet").GetString(),
                    url = item.GetProperty("link").GetString()
                });
            }
        }

        return JsonSerializer.Serialize(new { query, results }, new JsonSerializerOptions { WriteIndented = true });
    }

    private static string GetSimulatedResults(string query, int maxResults)
    {
        var simulatedResults = new List<object>
        {
            new { title = $"Overview of {query}", snippet = $"A comprehensive introduction to {query}, covering key concepts, history, and current developments in the field.", url = $"https://example.com/overview-{Uri.EscapeDataString(query)}" },
            new { title = $"Recent advances in {query}", snippet = $"Researchers have made significant breakthroughs in {query} during 2025-2026, including new methodologies and practical applications.", url = $"https://example.com/advances-{Uri.EscapeDataString(query)}" },
            new { title = $"{query} - Wikipedia", snippet = $"{query} is a broad topic encompassing multiple disciplines. This article provides a neutral, well-sourced overview of the subject.", url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}" },
            new { title = $"Practical applications of {query}", snippet = $"Industry leaders are applying {query} in healthcare, finance, and education, yielding measurable improvements in efficiency and outcomes.", url = $"https://example.com/applications-{Uri.EscapeDataString(query)}" },
            new { title = $"Challenges and criticisms of {query}", snippet = $"Despite its promise, {query} faces challenges including ethical concerns, scalability issues, and ongoing academic debate about its limitations.", url = $"https://example.com/challenges-{Uri.EscapeDataString(query)}" },
            new { title = $"The future of {query}", snippet = $"Experts predict that {query} will transform multiple industries over the next decade, with emerging trends pointing toward wider adoption.", url = $"https://example.com/future-{Uri.EscapeDataString(query)}" },
            new { title = $"{query}: A beginner's guide", snippet = $"New to {query}? This guide breaks down the fundamentals, key terminology, and resources to get started.", url = $"https://example.com/beginners-guide-{Uri.EscapeDataString(query)}" },
        };

        var results = simulatedResults.Take(maxResults).ToList();

        return JsonSerializer.Serialize(
            new { query, note = "Simulated results (set GOOGLE_API_KEY and GOOGLE_SEARCH_ENGINE_ID for live search)", results },
            new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>Returns the tool functions for registration with the agent.</summary>
    public IList<AITool> AsAITools()
    {
        return [AIFunctionFactory.Create(SearchWebAsync, name: "search_web", target: this)];
    }
}

using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability so the agent can record and organise findings during research.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record key findings from web searches.")]
    public string SaveNote(
        [Description("Short title summarising the note")] string title,
        [Description("Detailed content of the note")] string content,
        [Description("Optional source URL for attribution")] string? sourceUrl = null)
    {
        var note = new Note(
            Id: _notes.Count + 1,
            Title: title,
            Content: content,
            SourceUrl: sourceUrl,
            CreatedAt: DateTime.UtcNow);

        _notes.Add(note);
        return $"Note #{note.Id} saved: \"{title}\"";
    }

    [Description("Lists all saved research notes.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Retrieves a specific note by its ID.")]
    public string GetNote([Description("The numeric ID of the note to retrieve")] int id)
    {
        var note = _notes.FirstOrDefault(n => n.Id == id);
        if (note is null)
        {
            return $"Note #{id} not found. Use list_notes to see available notes.";
        }

        return JsonSerializer.Serialize(note, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Deletes a note by its ID.")]
    public string DeleteNote([Description("The numeric ID of the note to delete")] int id)
    {
        var note = _notes.FirstOrDefault(n => n.Id == id);
        if (note is null)
        {
            return $"Note #{id} not found.";
        }

        _notes.Remove(note);
        return $"Note #{id} (\"{note.Title}\") deleted.";
    }

    /// <summary>Returns the tool functions for registration with the agent.</summary>
    public IList<AITool> AsAITools()
    {
        return
        [
            AIFunctionFactory.Create(SaveNote, name: "save_note", target: this),
            AIFunctionFactory.Create(ListNotes, name: "list_notes", target: this),
            AIFunctionFactory.Create(GetNote, name: "get_note", target: this),
            AIFunctionFactory.Create(DeleteNote, name: "delete_note", target: this),
        ];
    }

    /// <summary>Returns a read-only snapshot of all saved notes.</summary>
    public IReadOnlyList<Note> GetAllNotes() => _notes.AsReadOnly();

    public sealed record Note(int Id, string Title, string Content, string? SourceUrl, DateTime CreatedAt);
}

