35. var httpClientFactory = provider.GetRequiredService<IHttpClientFactory>();
36. 
37. var webSearch = new WebSearchTool(
38.     httpClientFactory.CreateClient(),
39.     configuration["GOOGLE_API_KEY"],
40.     configuration["GOOGLE_SEARCH_ENGINE_ID"]);
41. 
