43. 
44. var tools = new List<AITool>();
45. tools.AddRange(webSearch.AsAITools());
46. tools.AddRange(noteTaking.AsAITools());
47. 
48. // ── Agent ──────────────────────────────────────────────────────────
49. const string instructions = """
50.     You are a research agent. Your job is to thoroughly research a topic
51.     provided by the user by following these steps:
52. 
53.     1. Use the search_web tool to find information about the topic.
54.        Perform multiple searches with different queries to get broad coverage.
55.     2. Use the save_note tool to record key findings from each search.
56.        Include source URLs for attribution.
57.     3. After gathering enough information (at least 3-5 notes), use
58.        list_notes to review your collected research.
59.     4. Finally, produce a well-structured summary that synthesises your notes,
60.        organised with clear headings, key points, and source references.
61. 
62.     Be thorough but concise. Focus on factual, well-sourced information.
63.     """;
64. 
65. var agent = chatClient.AsAIAgent(
66.     instructions: instructions,
67.     name: "ResearchAgent",
68.     description: "An agent that researches topics using web search and note-taking tools",
69.     tools: tools,
70.     loggerFactory: loggerFactory);
71. 
72. // ── Run ────────────────────────────────────────────────────────────
73. Console.WriteLine("╔══════════════════════════════════════════╗");
74. Console.WriteLine("║        🔍  Research Agent  📝           ║");
75. Console.WriteLine("╠══════════════════════════════════════════╣");
76. Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
77. Console.WriteLine("╚══════════════════════════════════════════╝");
78. Console.WriteLine();
79. 
80. while (true)
81. {
82.     Console.Write("Topic> ");
83.     var topic = Console.ReadLine()?.Trim();
84. 
85.     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
86.     {
87.         Console.WriteLine("Goodbye!");
88.         break;
89.     }
90. 
91.     Console.WriteLine($"\nResearching: {topic}\n");
92. 
93.     try
94.     {
95.         var session = await agent.CreateSessionAsync(conversationId: Guid.NewGuid().ToString());
96. 
97.         var response = await agent.RunAsync(
98.             $"Please research the following topic and provide a comprehensive summary: {topic}",
